const body = $input.first().json.body;
const msgData = body?.data;
if (!msgData) return [];
const fromMe = msgData?.key?.fromMe;
if (fromMe) return []; // Ignorar mensagens enviadas pelo bot

const jid1 = msgData?.key?.remoteJid || '';
const jid2 = msgData?.key?.remoteJidAlt || '';
let telefone = jid1.includes('@s.whatsapp.net') ? jid1 : (jid2.includes('@s.whatsapp.net') ? jid2 : '');

const content = msgData?.message?.extendedTextMessage?.text || msgData?.message?.conversation || '';
const pushName = msgData?.pushName || 'Cliente';
telefone = telefone.replace('@s.whatsapp.net', '');

return [{
  json: {
    Telefone: telefone,
    Mensagem: content,
    NomeWpp: pushName
  }
}];

const url = $('Variaveis do sistema').item.json.backendUrl;
const token = $('Variaveis do sistema').item.json.apiToken;
const options = {
  method: 'GET',
  url: `${url}/servicos`,
  headers: { 'Authorization': `Bearer ${token}` }
};
try {
  const res = await $helpers.httpRequest(options);
  return JSON.stringify(res.map(s => ({id: s.id, nome: s.nome, preco: s.preco})));
} catch (e) { return 'Erro ao listar servicos'; }

