const url = $('Variaveis do sistema').item.json.backendUrl;
const token = $('Variaveis do sistema').item.json.apiToken;
const telefone = $('Extrair Dados').item.json.Telefone;
const options = {
  method: 'GET',
  url: `${url}/agendamentos/telefone/${telefone}`,
  headers: { 'Authorization': `Bearer ${token}` }
};
try {
  const res = await $helpers.httpRequest(options);
  if(!res.length) return 'Nenhum agendamento encontrado.';
  return JSON.stringify(res.map(a => ({id: a.id, data: a.data, status: a.status, profissional: a.profissional?.nome, servicos: a.servicos.map(s => s.nome)})));
} catch (e) { return 'Erro ao consultar'; }

const url = $('Variaveis do sistema').item.json.backendUrl;
const token = $('Variaveis do sistema').item.json.apiToken;
const telefone = $('Extrair Dados').item.json.Telefone;
try {
  // Buscar usuário por telefone primeiro para pegar o ID
  let userRes;
  try {
     userRes = await $helpers.httpRequest({ method: 'GET', url: `${url}/usuarios/telefone/${telefone}`, headers: { 'Authorization': `Bearer ${token}` } });
  } catch(e) {
     // Usuario não existe, precisa ser criado pela lógica original, assumimos que já existe graças à lógica de DB antes do webhook
     // Se a lógica do DB antes do agente existir, o DB Node criou.
  }

  // Como o DB cria sem nos dar o ID de forma fácil para a API, e a API agora aceita o admin criando, podemos modificar o backend para buscar por telefone dentro do criar, ou buscar aqui se tivéssemos um endpoint de usuários.
  // Vamos assumir que a API `POST /agendamentos` precise do usuarioId. Vamos adicionar um parâmetro opcional `telefoneCliente` nela para facilitar a vida do bot.

  const body = {
    profissionalId: this.getInputData()[0].json.profissionalId,
    servicos: [this.getInputData()[0].json.servicoId],
    data: this.getInputData()[0].json.dataIso,
    telefoneCliente: telefone // Enviamos isso para a API
  };
  const res = await $helpers.httpRequest({ method: 'POST', url: `${url}/agendamentos`, headers: { 'Authorization': `Bearer ${token}` }, body });
  return 'Agendamento criado com sucesso!';
} catch(e) { return 'Erro ao criar agendamento: ' + e.message; }

const url = $('Variaveis do sistema').item.json.backendUrl;
const token = $('Variaveis do sistema').item.json.apiToken;
const id = this.getInputData()[0].json.agendamentoId;
try {
  await $helpers.httpRequest({ method: 'DELETE', url: `${url}/agendamentos/${id}`, headers: { 'Authorization': `Bearer ${token}` } });
  return 'Agendamento cancelado com sucesso!';
} catch(e) { return 'Erro ao cancelar'; }

const url = $('Variaveis do sistema').item.json.backendUrl;
const token = $('Variaveis do sistema').item.json.apiToken;
const id = this.getInputData()[0].json.agendamentoId;
const data = this.getInputData()[0].json.dataIso;
try {
  await $helpers.httpRequest({ method: 'PATCH', url: `${url}/agendamentos/${id}/reagendar`, headers: { 'Authorization': `Bearer ${token}` }, body: { data } });
  return 'Agendamento reagendado com sucesso!';
} catch(e) { return 'Erro ao reagendar'; }
